COMMENT ON COLUMN RNTMGR2.MDXT_15DEE$.START1 IS 'Lower coordinate boundary (minimum value) for dimension 1.';
COMMENT ON COLUMN RNTMGR2.MDXT_15DEE$.END1 IS 'Upper coordinate boundary (maximum value) for dimension 1.';
COMMENT ON COLUMN RNTMGR2.MDXT_15DEE$.AVGMBRLEN1 IS 'Average length of the Minimum Bounding Rectangles (MBRs) along dimension 1.';
COMMENT ON COLUMN RNTMGR2.MDXT_15DEE$.START2 IS 'Lower coordinate boundary (minimum value) for dimension 2.';
COMMENT ON COLUMN RNTMGR2.MDXT_15DEE$.END2 IS 'Upper coordinate boundary (maximum value) for dimension 2.';

COMMENT ON TABLE RNTMGR2.MLS_BROKERS IS 'Stores real estate broker and brokerage firm information imported from external Multiple Listing Service (MLS) data sources.';
COMMENT ON COLUMN RNTMGR2.MLS_BROKERS.BROKER_UID IS 'Unique identifier assigned to the broker within the external source system.';
COMMENT ON COLUMN RNTMGR2.MLS_BROKERS.SOURCE_ID IS 'Identifier of the external data source; foreign key referencing PR_SOURCES.';
COMMENT ON COLUMN RNTMGR2.MLS_BROKERS.NAME IS 'Name of the real estate broker or brokerage firm.';
COMMENT ON COLUMN RNTMGR2.MLS_BROKERS.PHONE IS 'Contact telephone number for the broker or brokerage firm.';
COMMENT ON COLUMN RNTMGR2.MLS_BROKERS.URL IS 'Website address or profile link for the broker or brokerage firm.';

COMMENT ON TABLE RNTMGR2.MLS_LISTINGS IS 'Stores Multiple Listing Service (MLS) real estate listing records sourced from external feeds, linked to property public records and photo attachments.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS.MLS_ID IS 'System-generated unique primary key for the MLS listing record.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS.PROP_ID IS 'Foreign key referencing PR_PROPERTIES; identifies the associated property.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS.SOURCE_ID IS 'Foreign key referencing PR_SOURCES; identifies the external MLS feed or system providing the data.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS.MLS_NUMBER IS 'Unique listing identifier assigned by the Multiple Listing Service (MLS).';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS.QUERY_TYPE IS 'Category or type of query used to fetch the listing from the source feed.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS.LISTING_TYPE IS 'Classification of the listing (e.g., Single Family, Rental, Condo).';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS.LISTING_STATUS IS 'Current status of the listing (e.g., Active, Pending, Sold, Expired).';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS.PRICE IS 'Current listing or asking price of the property.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS.IDX_YN IS 'Flag (Y/N) indicating if the listing is permitted for Internet Data Exchange (IDX) display.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS.LISTING_BROKER IS 'Name of the brokerage office or broker representing the listing.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS.LISTING_DATE IS 'Date when the property was initially listed on the MLS.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS.SHORT_DESC IS 'Brief summary or headline description of the listing.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS.LINK_TEXT IS 'Display text used for hyperlinks navigating to the listing.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS.DESCRIPTION IS 'Full marketing description or remarks provided for the listing.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS.LAST_ACTIVE IS 'Date or timestamp when the listing was last confirmed active in the source feed.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS.GEO_LOCATION IS 'Spatial geometry (SDO_GEOMETRY) representing the geographic coordinates of the listing.';

COMMENT ON TABLE RNTMGR2.MLS_LISTINGS_ARCHIVE IS 'Archive table storing historical Multiple Listing Service (MLS) property listings, including pricing, status, descriptions, and spatial coordinates.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_ARCHIVE.MLS_ID IS 'Unique identifier for the archived MLS listing record.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_ARCHIVE.PROP_ID IS 'Identifier of the associated property record.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_ARCHIVE.SOURCE_ID IS 'Identifier of the MLS data source or provider.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_ARCHIVE.MLS_NUMBER IS 'External Multiple Listing Service (MLS) number.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_ARCHIVE.QUERY_TYPE IS 'Type or categorization of the query used to pull the listing.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_ARCHIVE.LISTING_TYPE IS 'Classification of the listing (e.g., Sale, Rental).';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_ARCHIVE.LISTING_STATUS IS 'Status of the listing (e.g., Active, Pending, Sold, Expired).';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_ARCHIVE.PRICE IS 'Listed price of the property.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_ARCHIVE.IDX_YN IS 'Flag indicating if the listing is eligible for Internet Data Exchange (IDX) display (Y/N).';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_ARCHIVE.LISTING_BROKER IS 'Name of the listing broker or brokerage firm.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_ARCHIVE.LISTING_DATE IS 'Date the listing was officially posted or created.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_ARCHIVE.SHORT_DESC IS 'Brief summary or headline description of the listing.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_ARCHIVE.LINK_TEXT IS 'Hyperlink text or URL reference related to the listing.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_ARCHIVE.DESCRIPTION IS 'Full textual description of the property listing.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_ARCHIVE.LAST_ACTIVE IS 'Date and time when the listing was last verified as active.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_ARCHIVE.GEO_LOCATION IS 'Oracle Spatial geometry representing the geographic location of the property.';

COMMENT ON TABLE RNTMGR2.MLS_LISTINGS_V IS 'View over MLS_LISTINGS that presents Multiple Listing Service property listings along with a computed record checksum for change detection.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_V.MLS_ID IS 'Unique identifier for the MLS listing record.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_V.PROP_ID IS 'Identifier of the property associated with this MLS listing.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_V.SOURCE_ID IS 'Identifier of the MLS feed or data source.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_V.MLS_NUMBER IS 'External MLS listing reference number.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_V.QUERY_TYPE IS 'Type or criteria used when querying the MLS system.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_V.LISTING_TYPE IS 'Type of listing (e.g., rental, sale).';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_V.LISTING_STATUS IS 'Current status of the listing (e.g., Active, Pending, Sold).';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_V.PRICE IS 'Listing price for the property.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_V.IDX_YN IS 'Flag indicating if the listing is enabled for Internet Data Exchange (Y/N).';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_V.LISTING_BROKER IS 'Name of the listing brokerage or agent.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_V.LISTING_DATE IS 'Date the property was listed on the MLS.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_V.SHORT_DESC IS 'Short summary or headline description of the listing.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_V.LINK_TEXT IS 'Link text or URL pointing to the external MLS listing.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_V.DESCRIPTION IS 'Detailed remarks or full description of the listing.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_V.LAST_ACTIVE IS 'Timestamp when the listing was last confirmed active.';
COMMENT ON COLUMN RNTMGR2.MLS_LISTINGS_V.CHECKSUM IS 'System-generated checksum hash used for optimistic locking and change tracking.';

COMMENT ON TABLE RNTMGR2.MLS_PHOTOS IS 'Stores image URLs and metadata for photographs associated with MLS property listings.';
COMMENT ON COLUMN RNTMGR2.MLS_PHOTOS.MLS_ID IS 'Unique identifier for the MLS listing; foreign key referencing MLS_LISTINGS.';
COMMENT ON COLUMN RNTMGR2.MLS_PHOTOS.PHOTO_SEQ IS 'Sequence number indicating the display order of the photo for the listing.';
COMMENT ON COLUMN RNTMGR2.MLS_PHOTOS.PHOTO_URL IS 'Web URL or file path where the listing photo is hosted.';
COMMENT ON COLUMN RNTMGR2.MLS_PHOTOS.PHOTO_DESC IS 'Optional caption or descriptive text for the photograph.';

COMMENT ON TABLE RNTMGR2.MLS_PHOTOS_ARCHIVE IS 'Archive table storing historical photos and metadata associated with Multiple Listing Service (MLS) property listings.';
COMMENT ON COLUMN RNTMGR2.MLS_PHOTOS_ARCHIVE.MLS_ID IS 'Identifier of the associated MLS property listing.';
COMMENT ON COLUMN RNTMGR2.MLS_PHOTOS_ARCHIVE.PHOTO_SEQ IS 'Display sequence or order number of the photo for the listing.';
COMMENT ON COLUMN RNTMGR2.MLS_PHOTOS_ARCHIVE.PHOTO_URL IS 'URL or storage path location of the property photograph.';
COMMENT ON COLUMN RNTMGR2.MLS_PHOTOS_ARCHIVE.PHOTO_DESC IS 'Description, caption, or label for the listing photo.';

COMMENT ON TABLE RNTMGR2.MLS_PHOTOS_V IS 'View over the MLS_PHOTOS table that provides property listing photo details along with a calculated record-level checksum for data validation and concurrency control.';
COMMENT ON COLUMN RNTMGR2.MLS_PHOTOS_V.MLS_ID IS 'Unique identifier of the associated MLS property listing.';
COMMENT ON COLUMN RNTMGR2.MLS_PHOTOS_V.PHOTO_SEQ IS 'Sequence or display order number for the photo within the MLS listing.';
COMMENT ON COLUMN RNTMGR2.MLS_PHOTOS_V.PHOTO_URL IS 'URL or storage path of the MLS listing photo.';
COMMENT ON COLUMN RNTMGR2.MLS_PHOTOS_V.PHOTO_DESC IS 'Optional description or caption for the photo.';
COMMENT ON COLUMN RNTMGR2.MLS_PHOTOS_V.CHECKSUM IS 'Calculated row checksum used to detect changes and support optimistic locking.';

COMMENT ON TABLE RNTMGR2.MLS_PRICE_RANGES IS 'Stores historical and current statistical price ranges (min, median, max across rating tiers A, B, and C) for MLS property listings categorized by area, listing type, and source.';
COMMENT ON COLUMN RNTMGR2.MLS_PRICE_RANGES.ZCODE IS 'Geographic zone or ZIP code for the price range aggregation.';
COMMENT ON COLUMN RNTMGR2.MLS_PRICE_RANGES.LISTING_TYPE IS 'Category or type of property listing (e.g., Rental, Sale).';
COMMENT ON COLUMN RNTMGR2.MLS_PRICE_RANGES.QUERY_TYPE IS 'Type of query or criteria used to generate the price statistics.';
COMMENT ON COLUMN RNTMGR2.MLS_PRICE_RANGES.RANGE_DATE IS 'Effective date or snapshot date of the price range calculation.';
COMMENT ON COLUMN RNTMGR2.MLS_PRICE_RANGES.SOURCE_ID IS 'Identifier of the external data source; references PR_SOURCES.SOURCE_ID.';
COMMENT ON COLUMN RNTMGR2.MLS_PRICE_RANGES.COUNTY IS 'County name where the properties are located.';
COMMENT ON COLUMN RNTMGR2.MLS_PRICE_RANGES.STATE IS 'State code or abbreviation where the properties are located.';
COMMENT ON COLUMN RNTMGR2.MLS_PRICE_RANGES.CURRENT_YN IS 'Indicates if the record represents the current active price range (Y/N).';
COMMENT ON COLUMN RNTMGR2.MLS_PRICE_RANGES.NAME IS 'Descriptive name of the geographic area, zone, or price range group.';
COMMENT ON COLUMN RNTMGR2.MLS_PRICE_RANGES.A_MAX IS 'Maximum price observed for Tier A properties.';
COMMENT ON COLUMN RNTMGR2.MLS_PRICE_RANGES.A_MEDIAN IS 'Median price observed for Tier A properties.';
COMMENT ON COLUMN RNTMGR2.MLS_PRICE_RANGES.A_MIN IS 'Minimum price observed for Tier A properties.';
COMMENT ON COLUMN RNTMGR2.MLS_PRICE_RANGES.B_MEDIAN IS 'Median price observed for Tier B properties.';
COMMENT ON COLUMN RNTMGR2.MLS_PRICE_RANGES.C_MAX IS 'Maximum price observed for Tier C properties.';
COMMENT ON COLUMN RNTMGR2.MLS_PRICE_RANGES.C_MEDIAN IS 'Median price observed for Tier C properties.';
COMMENT ON COLUMN RNTMGR2.MLS_PRICE_RANGES.C_MIN IS 'Minimum price observed for Tier C properties.';
COMMENT ON COLUMN RNTMGR2.MLS_PRICE_RANGES.TOTAL IS 'Total count of listings included in this price range calculation.';

COMMENT ON TABLE RNTMGR2.MLS_RETS_RESPONSES IS 'Stores raw XML responses and processing status from RETS (Real Estate Transaction Standard) queries for MLS property listings.';
COMMENT ON COLUMN RNTMGR2.MLS_RETS_RESPONSES.MLS_NUMBER IS 'Identifier or listing number of the property within the MLS system.';
COMMENT ON COLUMN RNTMGR2.MLS_RETS_RESPONSES.DATE_FOUND IS 'Date and time when the RETS query response was retrieved or recorded.';
COMMENT ON COLUMN RNTMGR2.MLS_RETS_RESPONSES.QUERY_TYPE IS 'Specifies the category or type of RETS query executed.';
COMMENT ON COLUMN RNTMGR2.MLS_RETS_RESPONSES.PROCESSED_YN IS 'Flag indicating whether the RETS response data has been processed (Y/N).';
COMMENT ON COLUMN RNTMGR2.MLS_RETS_RESPONSES.RESPONSE IS 'Raw XML payload returned by the RETS server for the query.';
COMMENT ON COLUMN RNTMGR2.MLS_RETS_RESPONSES.SOURCE_ID IS 'Identifier for the source MLS feed or provider configuration.';

COMMENT ON TABLE RNTMGR2.PR_AGENT_COURSES IS 'Tracks courses completed by licensed agents, including completion dates and earned credit hours.';
COMMENT ON COLUMN RNTMGR2.PR_AGENT_COURSES.LICENSE_NUMBER IS 'License number of the agent who completed the course. References PR_LICENSED_AGENTS.';
COMMENT ON COLUMN RNTMGR2.PR_AGENT_COURSES.COURSE_NUMBER IS 'Unique identifier of the completed course. References PR_COURSES.';
COMMENT ON COLUMN RNTMGR2.PR_AGENT_COURSES.COURSE_DATE IS 'Date on which the course was completed by the agent.';
COMMENT ON COLUMN RNTMGR2.PR_AGENT_COURSES.COURSE_CREDIT_HOURS IS 'Number of continuing education credit hours earned for completing the course.';

COMMENT ON TABLE RNTMGR2.PR_BUILDINGS IS 'Stores details of individual buildings located on a property, including their physical dimensions and construction year.';
COMMENT ON COLUMN RNTMGR2.PR_BUILDINGS.BUILDING_ID IS 'Unique identifier and primary key for the building record.';
COMMENT ON COLUMN RNTMGR2.PR_BUILDINGS.PROP_ID IS 'Foreign key referencing PR_PROPERTIES.PROP_ID, identifying the property where the building is situated.';
COMMENT ON COLUMN RNTMGR2.PR_BUILDINGS.BUILDING_NAME IS 'Name or identifier designation of the building.';
COMMENT ON COLUMN RNTMGR2.PR_BUILDINGS.YEAR_BUILT IS 'Four-digit calendar year in which the building was constructed.';
COMMENT ON COLUMN RNTMGR2.PR_BUILDINGS.SQ_FT IS 'Total floor area of the building measured in square feet.';

COMMENT ON TABLE RNTMGR2.PR_BUILDING_FEATURES IS 'Intersection table mapping specific features and amenities to buildings in a many-to-many relationship.';
COMMENT ON COLUMN RNTMGR2.PR_BUILDING_FEATURES.FCODE IS 'Foreign key identifying the feature code assigned to the building, referencing PR_FEATURE_CODES.';
COMMENT ON COLUMN RNTMGR2.PR_BUILDING_FEATURES.BUILDING_ID IS 'Foreign key identifying the building associated with the feature, referencing PR_BUILDINGS.';

COMMENT ON TABLE RNTMGR2.PR_BUILDING_USAGE IS 'Associative table mapping buildings to their designated usage classification codes.';
COMMENT ON COLUMN RNTMGR2.PR_BUILDING_USAGE.UCODE IS 'Identifier of the usage classification code; foreign key referencing PR_USAGE_CODES.';
COMMENT ON COLUMN RNTMGR2.PR_BUILDING_USAGE.BUILDING_ID IS 'Identifier of the building; foreign key referencing PR_BUILDINGS.';

COMMENT ON TABLE RNTMGR2.PR_CITY_ZIPCODES IS 'Associative table that maps cities to their corresponding postal or ZIP codes.';
COMMENT ON COLUMN RNTMGR2.PR_CITY_ZIPCODES.CITY_ID IS 'Unique identifier of the city associated with the postal code.';
COMMENT ON COLUMN RNTMGR2.PR_CITY_ZIPCODES.ZIPCODE IS 'Postal or ZIP code assigned to the designated city.';

COMMENT ON TABLE RNTMGR2.PR_COMMERCIAL_PROPERTIES_V IS 'View providing property details and usage classification for commercial properties, filtered from PR_PROPERTIES via PR_PROPERTY_USAGE and PR_USAGE_CODES where commercial_yn is ''Y''.';
COMMENT ON COLUMN RNTMGR2.PR_COMMERCIAL_PROPERTIES_V.PROP_ID IS 'Unique identifier for the property from PR_PROPERTIES.';
COMMENT ON COLUMN RNTMGR2.PR_COMMERCIAL_PROPERTIES_V.SOURCE_ID IS 'Identifier indicating the origin or external source system for the property data.';
COMMENT ON COLUMN RNTMGR2.PR_COMMERCIAL_PROPERTIES_V.SOURCE_PK IS 'Original primary key identifier from the external source system.';
COMMENT ON COLUMN RNTMGR2.PR_COMMERCIAL_PROPERTIES_V.ADDRESS1 IS 'Primary street address line of the commercial property.';
