COMMENT ON TABLE RNTMGR2.PR_OWNERS IS 'Stores master records of property owners, including individuals and corporate entities, associated with real estate properties and sales transactions.';
COMMENT ON COLUMN RNTMGR2.PR_OWNERS.OWNER_ID IS 'Unique identifier and primary key for the property owner.';
COMMENT ON COLUMN RNTMGR2.PR_OWNERS.OWNER_NAME IS 'Full legal name of the individual or entity that owns the property.';
COMMENT ON COLUMN RNTMGR2.PR_OWNERS.OWNER_TYPE IS 'Classification or category of the owner (e.g., Individual, Corporation, Trust).';

COMMENT ON TABLE RNTMGR2.PR_PRINCIPALS IS 'Stores principal entities (such as users, roles, or groups) used for access control, permissions, or system entity classification.';
COMMENT ON COLUMN RNTMGR2.PR_PRINCIPALS.PN_ID IS 'Unique identifier and primary key for the principal.';
COMMENT ON COLUMN RNTMGR2.PR_PRINCIPALS.PN_TYPE IS 'Specifies the classification or category of the principal (e.g., USER, GROUP, ROLE).';
COMMENT ON COLUMN RNTMGR2.PR_PRINCIPALS.PN_NAME IS 'Name or identifier representing the principal entity.';

COMMENT ON TABLE RNTMGR2.PR_PRINCIPALS_TMP IS 'Temporary staging table used for storing and processing corporate principal and officer records during data loading or batch operations.';
COMMENT ON COLUMN RNTMGR2.PR_PRINCIPALS_TMP.CORP_NUMBER IS 'Corporate registration or identification number associated with the principal.';
COMMENT ON COLUMN RNTMGR2.PR_PRINCIPALS_TMP.PN_TYPE IS 'Type or classification code of the principal (e.g., individual or corporate entity).';
COMMENT ON COLUMN RNTMGR2.PR_PRINCIPALS_TMP.PN_NAME IS 'Full name of the corporate principal, officer, or entity.';
COMMENT ON COLUMN RNTMGR2.PR_PRINCIPALS_TMP.TITLE_CODE IS 'Code indicating the official title or executive role held by the principal.';
COMMENT ON COLUMN RNTMGR2.PR_PRINCIPALS_TMP.PN_ID IS 'Numeric unique identifier for the principal record.';

COMMENT ON TABLE RNTMGR2.PR_PRINCIPALS_V IS 'View over PR_PRINCIPALS providing principal details along with a computed checksum for optimistic locking and data integrity verification.';
COMMENT ON COLUMN RNTMGR2.PR_PRINCIPALS_V.PN_ID IS 'Unique identifier for the principal.';
COMMENT ON COLUMN RNTMGR2.PR_PRINCIPALS_V.PN_TYPE IS 'Type or classification category of the principal.';
COMMENT ON COLUMN RNTMGR2.PR_PRINCIPALS_V.PN_NAME IS 'Name or title of the principal.';
COMMENT ON COLUMN RNTMGR2.PR_PRINCIPALS_V.CHECKSUM IS 'Calculated row checksum used to detect data changes and support optimistic locking.';

COMMENT ON TABLE RNTMGR2.PR_PRINCIPAL_LOCATIONS IS 'Associative table mapping relationships between principals and their assigned or associated locations.';
COMMENT ON COLUMN RNTMGR2.PR_PRINCIPAL_LOCATIONS.LOC_ID IS 'Unique identifier for the location; part of the composite primary key.';
COMMENT ON COLUMN RNTMGR2.PR_PRINCIPAL_LOCATIONS.PN_ID IS 'Unique identifier for the principal; part of the composite primary key.';

COMMENT ON TABLE RNTMGR2.PR_PRINCIPAL_LOCATIONS_V IS 'View displaying principal and location associations from PR_PRINCIPAL_LOCATIONS, including a computed checksum for optimistic locking.';
COMMENT ON COLUMN RNTMGR2.PR_PRINCIPAL_LOCATIONS_V.LOC_ID IS 'Unique identifier for the location.';
COMMENT ON COLUMN RNTMGR2.PR_PRINCIPAL_LOCATIONS_V.PN_ID IS 'Unique identifier for the principal entity.';
COMMENT ON COLUMN RNTMGR2.PR_PRINCIPAL_LOCATIONS_V.CHECKSUM IS 'System-generated checksum of record values, used for optimistic concurrency control and data integrity validation.';

COMMENT ON TABLE RNTMGR2.PR_PROCESSED IS 'Tracks processed property parcel records, typically used as a processing log or staging table by company and parcel identifier.';
COMMENT ON COLUMN RNTMGR2.PR_PROCESSED.CO_NO IS 'Company or county number associated with the processed parcel.';
COMMENT ON COLUMN RNTMGR2.PR_PROCESSED.PARCEL_ID IS 'Unique identifier of the property parcel.';

COMMENT ON TABLE RNTMGR2.PR_PROPERTIES_V IS 'View over the PR_PROPERTIES table providing property details, geographic location, and a calculated row checksum for change detection.';
COMMENT ON COLUMN RNTMGR2.PR_PROPERTIES_V.PROP_ID IS 'Unique identifier for the property.';
COMMENT ON COLUMN RNTMGR2.PR_PROPERTIES_V.SOURCE_ID IS 'Identifier referencing the source system or data feed provider.';
