COMMENT ON COLUMN RNTMGR2.PR_PROPERTY_LISTINGS_V.CHECKSUM IS 'Calculated record checksum used for optimistic locking and data integrity verification.';

COMMENT ON TABLE RNTMGR2.PR_PROPERTY_OWNERS IS 'Associative table linking properties to their owners, storing ownership relationships and the owner''s mailing address information.';
COMMENT ON COLUMN RNTMGR2.PR_PROPERTY_OWNERS.CITY IS 'City name for the owner''s mailing address.';
COMMENT ON COLUMN RNTMGR2.PR_PROPERTY_OWNERS.STATE IS 'State code or abbreviation for the owner''s mailing address.';
COMMENT ON COLUMN RNTMGR2.PR_PROPERTY_OWNERS.ZIPCODE IS 'Postal code or ZIP code for the owner''s mailing address.';
COMMENT ON COLUMN RNTMGR2.PR_PROPERTY_OWNERS.OWNER_ID IS 'Foreign key referencing PR_OWNERS; identifies the property owner.';
