COMMENT ON COLUMN RNTMGR2.PR_PROPERTY_PHOTOS.FILENAME IS 'Original or stored filename of the property photo.';

COMMENT ON TABLE RNTMGR2.PR_PROPERTY_SALES IS 'Stores historical and recorded property sale transactions, documenting ownership transfers, transaction prices, deed classifications, and plat recording references.';
COMMENT ON COLUMN RNTMGR2.PR_PROPERTY_SALES.PROP_ID IS 'Foreign key referencing PR_PROPERTIES; uniquely identifies the property involved in the sale.';
COMMENT ON COLUMN RNTMGR2.PR_PROPERTY_SALES.NEW_OWNER_ID IS 'Foreign key referencing PR_OWNERS; identifies the buyer or acquiring owner.';
