COMMENT ON COLUMN RNTMGR2.PR_PUMS_VALUES.VALUE_AMOUNT IS 'Numeric amount corresponding to the specified percentile and value type.';

COMMENT ON TABLE RNTMGR2.PR_SDF IS 'Stores parcel sales transfer and assessment data, commonly reflecting standard property appraiser Sales Data File (SDF) records.';
