COMMENT ON COLUMN RNTMGR2.PR_TAXES.TAX_AMOUNT IS 'Total property tax amount assessed or billed for the specified tax year.';
COMMENT ON COLUMN RNTMGR2.PR_TAXES.CURRENT_YN IS 'Flag indicating if this record represents the current active tax assessment (Y/N).';

COMMENT ON TABLE RNTMGR2.PR_UCODE_DATA IS 'Stores aggregated property metrics, including total property count and square footage, categorized by city and property usage code.';
COMMENT ON COLUMN RNTMGR2.PR_UCODE_DATA.CITY_ID IS 'Unique identifier for the city.';
