COMMENT ON COLUMN RNTMGR2.RNT_ACCOUNTS_PAYABLE_ALL_V.INVOICE_NUMBER IS 'Supplier or vendor invoice number for reference.';
COMMENT ON COLUMN RNTMGR2.RNT_ACCOUNTS_PAYABLE_ALL_V.CHECKSUM IS 'Computed MD5/checksum hash of the row data for optimistic locking and integrity validation.';

COMMENT ON TABLE RNTMGR2.RNT_ACCOUNTS_PAYABLE_PROP_V IS 'View displaying accounts payable records categorized as other/property expenses, combined with payment allocation dates and property references.';
