COMMENT ON TABLE RNTMGR2.RNT_ACCOUNTS_RECEIVABLE_ALL_V IS 'View over RNT_ACCOUNTS_RECEIVABLE exposing all accounts receivable records along with a computed record checksum for data integrity or optimistic locking.';
